CREATE SCHEMA app;
CREATE TABLE app.users (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE app.secrets (id BIGSERIAL PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO app.users(email) VALUES ('one@example.com'), ('two@example.com');
CREATE USER codebridge WITH PASSWORD 'codebridge';
GRANT CONNECT ON DATABASE app TO codebridge;
GRANT USAGE ON SCHEMA app TO codebridge;
GRANT SELECT ON ALL TABLES IN SCHEMA app TO codebridge;
ALTER DEFAULT PRIVILEGES IN SCHEMA app GRANT SELECT ON TABLES TO codebridge;
CREATE USER codebridge_writer WITH PASSWORD 'codebridge_writer';
GRANT CONNECT ON DATABASE app TO codebridge_writer;
GRANT USAGE ON SCHEMA app TO codebridge_writer;
GRANT SELECT, UPDATE, DELETE ON ALL TABLES IN SCHEMA app TO codebridge_writer;
